        let intruder_password = accounts
            .issue_credential(intruder_id, "Phone".into())
            .await
            .unwrap()
            .password
            .expose()
            .to_owned();

        let body = multiget_xml(&[resource_href(&principal_id, active, "x")]);
        let app = build_caldav_router(accounts);
        let (status, _resp) = report_request(
            app,
