) -> Result<(), sqlx::Error> {
    sqlx::query(
        "INSERT INTO caldav_event_resources (
            event_id, calendar_id, uid, resource_name, created_at, updated_at
         ) VALUES (?, ?, ?, ?, 1, 1)",
    )
    .bind(event_id)
    .bind(calendar_id)
    .bind(uid)
    .bind(name)
    .execute(pool)
    .await
