    .bind(timing.all_day_end_date)
    .bind(actor_user_id)
    .bind(actor_user_id)
    .bind(now)
    .bind(now)
    .bind(&recurrence_rule)
    .execute(&mut *transaction)
    .await?;
    let event_id = result.last_insert_rowid();
