    let audit_count: i64 = sqlx::query_scalar(
        "SELECT COUNT(*) FROM audit_log
         WHERE action = 'event.create' AND actor_user_id = ? AND target_type = 'event'",
    )
    .bind(user_id)
    .fetch_one(&pool)
    .await
    .unwrap();
    assert_eq!(
        audit_count, 1,
        "successful create must record an event.create audit entry"
    );
    let _ = temp_dir;
}
